// barPercentHeight returns the CSS height percentage for a vertical bar.
func barPercentHeight(value, max float64) string {
	if max <= 0 {
		return "0%"
	}
	pct := (value / max) * 100
	if pct < 0 {
		pct = 0
	}
	if pct > 100 {
		pct = 100
	}
	return fmt.Sprintf("%.1f%%", math.Round(pct*10)/10)
}

// truncateLabel truncates a string to maxLen characters with an ellipsis.
func truncateLabel(s string, maxLen int) string {
	if len(s) <= maxLen {
		return s
	}
	return s[:maxLen-1] + "…"
}

